SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.visible, m.STATUS, ifnull( m.perms, '' ) AS perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time FROM sys_menu m LEFT JOIN sys_role_menu rm ON rm.menu_id = m.menu_id LEFT JOIN sys_user u ON u.role_id = rm.role_id LEFT JOIN sys_role r ON r.role_id = u.role_id WHERE u.user_id = #{params.userId}
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
order by m.parent_id, m.order_num

select count(1)
from sys_menu
where parent_id = #{menuId}
